// #6a993d795019333734edc22d (#edc22d) — жизненный цикл бизнеса глазами Super Admin (кейсы BIZ-LC-001, 003–006).
// Данные: одноразовый бизнес «QA-AUTO-LC …», создаётся через форму (почты на example.com — письмо не уходит, это нормально).
// Блокируется и удаляется ТОЛЬКО этот бизнес; удаление — последний тест и страховка в afterAll. По приглашению не вступаем (пароль).
// Вручную (не автоматизируется): BIZ-LC-009 вход пользователей / ссылки кандидатов заблокированного бизнеса, BIZ-LC-010 старые сессии удалённого.
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';

const ADMIN_STATE = path.resolve(__dirname, '../../../auth/admin.json');
test.use({ storageState: ADMIN_STATE });
test.describe.configure({ mode: 'serial' });

const stamp = runStamp();
const BUSINESS_NAME = `QA-AUTO-LC ${stamp}`;
const CONTACT = { name: 'QA-AUTO איש קשר', role: 'QA-AUTO תפקיד', phone: '0500000000', email: 'qa+auto-lc-contact@example.com' };
const MANAGER = { name: `QA-AUTO מנהל ${stamp}`, email: 'qa+auto-lc@example.com' };
const NOTE = 'QA-AUTO: одноразовый бизнес автотеста #edc22d, удаляется в конце';

let businessId = '';
let firstToken = '';
let deleted = false;

const statusRegion = (page: Page) => page.getByRole('region', { name: 'סטטוס החשבון' });
const inviteRow = (page: Page) => page.getByRole('region', { name: 'הזמנות' }).getByRole('row').filter({ hasText: MANAGER.email });

async function openCard(page: Page) {
  const loaded = page.waitForResponse((r) => r.url().includes('/rpc/admin_get_business') && r.request().method() === 'POST');
  await page.goto(`/admin/businesses/${businessId}`);
  expect((await loaded).ok()).toBeTruthy();
  await expect(page.getByRole('heading', { level: 1, name: BUSINESS_NAME })).toBeVisible();
}

/** Смена статуса через карточку: «סטטוס חדש» → «עדכון סטטוס» → «אישור». */
async function changeStatus(page: Page, label: 'פעיל' | 'חסום' | 'נמחק') {
  await statusRegion(page).getByRole('combobox', { name: 'סטטוס חדש' }).selectOption({ label });
  await statusRegion(page).getByRole('button', { name: 'עדכון סטטוס' }).click();
  await expect(page.getByText('לאשר את שינוי הסטטוס?')).toBeVisible();
  const saved = page.waitForResponse((r) => r.url().includes('/rpc/admin_set_business_status'));
  await page.getByRole('button', { name: 'אישור', exact: true }).click();
  expect((await saved).ok(), `admin_set_business_status → ${label}`).toBeTruthy();
}

async function expectJoinForm(guest: Page, token: string) {
  await guest.goto(`/invite/${token}`);
  await expect(guest.getByRole('heading', { level: 1, name: 'הצטרפות לחשבון העסק' })).toBeVisible();
  await expect(guest.getByRole('textbox', { name: 'סיסמה', exact: true })).toBeVisible();
}

test.describe('Жизненный цикл бизнеса — Super Admin (#6a993d795019333734edc22d)', () => {
  test.afterAll(async ({ browser }) => {
    if (!businessId || deleted) return;
    const ctx = await browser.newContext({ storageState: ADMIN_STATE, baseURL: test.info().project.use.baseURL, locale: 'he-IL' });
    try {
      const page = await ctx.newPage();
      await openCard(page);
      await changeStatus(page, 'נמחק');
      await expect(page.getByText('בית העסק נמחק')).toBeVisible();
    } finally {
      await ctx.close();
    }
  });

  test('создание со всеми полями — карточка, ссылка первому менеджеру с копированием, ссылка открывает форму @desktop @data #6a993d795019333734edc22d', async ({ page, asUser, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    await page.goto('/admin/businesses/new');
    await expect(page.getByRole('heading', { level: 1, name: 'יצירת בית עסק' })).toBeVisible();
    // Треб.5 «שפת ברירת מחדל — עברית»; статус по умолчанию — פעיל.
    await expect(page.getByRole('combobox', { name: 'שפת ברירת מחדל' }).locator('option:checked')).toHaveText('עברית');
    await expect(page.getByRole('combobox', { name: 'סטטוס החשבון' }).locator('option:checked')).toHaveText('פעיל');

    const biz = page.getByRole('group', { name: 'פרטי העסק' });
    await biz.getByRole('textbox', { name: 'שם העסק (חובה)' }).fill(BUSINESS_NAME);
    await biz.getByRole('textbox', { name: 'תחום פעילות (חובה)' }).fill('QA-AUTO בדיקות');
    const contact = page.getByRole('group', { name: 'איש קשר' });
    await contact.getByRole('textbox', { name: 'שם איש הקשר (חובה)' }).fill(CONTACT.name);
    await contact.getByRole('textbox', { name: 'תפקיד איש הקשר (חובה)' }).fill(CONTACT.role);
    await contact.getByRole('textbox', { name: 'טלפון (חובה)' }).fill(CONTACT.phone);
    await contact.getByRole('textbox', { name: 'מייל (חובה)' }).fill(CONTACT.email);
    const manager = page.getByRole('group', { name: 'מנהל/ת החשבון הראשון/ה' });
    await manager.getByRole('textbox', { name: 'שם מלא (חובה)' }).fill(MANAGER.name);
    await manager.getByRole('textbox', { name: 'מייל (חובה)' }).fill(MANAGER.email);
    await page.getByRole('textbox', { name: 'הערה פנימית (לא חובה)' }).fill(NOTE);

    const created = page.waitForResponse((r) => r.url().includes('/functions/v1/admin-create-business'));
    await page.getByRole('button', { name: 'יצירת בית העסק' }).click();
    const createdRes = await created;
    expect(createdRes.status(), 'admin-create-business').toBe(201);
    const body = (await createdRes.json()) as { business_id: string; invitation: { token: string; status: string } };
    businessId = body.business_id;
    firstToken = body.invitation.token;
    test.info().annotations.push({ type: 'test-data', description: `business ${BUSINESS_NAME} ${businessId} (удаляется в конце)` });
    await page.waitForURL(`**/admin/businesses/${businessId}`);

    // AC1: создана запись бизнеса со всеми полями.
    await expect(page.getByRole('heading', { level: 1, name: BUSINESS_NAME })).toBeVisible();
    const details = page.getByRole('region', { name: 'פרטי העסק' });
    await expect(details).toContainText(`${CONTACT.name}, ${CONTACT.role}`);
    await expect(details).toContainText(CONTACT.phone);
    await expect(details).toContainText(CONTACT.email);
    await expect(details).toContainText('עברית');
    await expect(details).toContainText(NOTE);
    await expect(statusRegion(page).getByRole('combobox', { name: 'סטטוס חדש' }).locator('option:checked')).toHaveText('פעיל');

    // FL-01 ш.1 / реджект 05.10 Р2: сразу после сохранения — полная ссылка и копирование.
    const createdBlock = page.getByRole('region', { name: 'בית העסק נוצר' });
    const link = `${new URL(page.url()).origin}/invite/${firstToken}`;
    await expect(createdBlock.getByText(link, { exact: true })).toBeVisible();
    await createdBlock.getByRole('button', { name: 'העתקת הקישור' }).click();
    await expect(createdBlock.getByRole('status')).toHaveText('הקישור הועתק');
    expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(link);

    // FL-01 ш.2: приглашение первого менеджера — ממתינה.
    await expect(inviteRow(page)).toContainText('מנהל/ת חשבון');
    await expect(inviteRow(page)).toContainText('ממתינה');

    const guest = await asUser('guest');
    await expectJoinForm(guest, firstToken);
  });

  test('повторная отправка приглашения — новая ссылка, прежняя «ההזמנה בוטלה» @desktop @data #6a993d795019333734edc22d', async ({ page, asUser }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await openCard(page);
    const resent = page.waitForResponse((r) => r.url().includes('/functions/v1/resend-invitation'));
    await inviteRow(page).getByRole('button', { name: 'שליחה מחדש' }).click();
    const res = await resent;
    expect(res.status()).toBe(200);
    const newToken = ((await res.json()) as { invitation: { token: string } }).invitation.token;
    expect(newToken).toBeTruthy();
    expect(newToken).not.toBe(firstToken);
    await expect(inviteRow(page).getByRole('status')).toHaveText('נוצר קישור חדש, אך שליחת המייל נכשלה. אפשר להעתיק אותו.');
    await expect(inviteRow(page)).toContainText('ממתינה');

    // Треб.8: «שליחה חדשה מבטלת את הקודמת».
    const guest = await asUser('guest');
    await guest.goto(`/invite/${firstToken}`);
    await expect(guest.getByRole('heading', { level: 1, name: 'ההזמנה בוטלה' })).toBeVisible();
    await expect(guest.getByText('נשלחה הזמנה חדשה במקום ההזמנה הזו')).toBeVisible();
    await expect(guest.getByRole('textbox')).toHaveCount(0);
    await expectJoinForm(guest, newToken);
    firstToken = newToken;
  });

  test('просмотр карточки записан в журнал доступа «צפייה בפרטי בית עסק» @desktop @data #6a993d795019333734edc22d', async ({ page }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await openCard(page);
    // Треб.7: «כל צפייה של Super Admin בפרטי עסק ובמשתמשיו נרשמת ברישום גישה».
    await page.goto('/admin/access-log');
    await expect(page.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible();
    const rows = page.getByRole('table', { name: /^רישום גישה/ }).getByRole('row').filter({ hasText: BUSINESS_NAME }).filter({ hasText: 'צפייה בפרטי בית עסק' });
    await expect(rows.first()).toBeVisible();
    await expect(rows.first()).toContainText('מנהל מערכת');
    const today = new Date().toLocaleDateString('he-IL', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Asia/Jerusalem' });
    await expect(rows.first().getByRole('cell').first()).toContainText(today);
  });

  test('блокировка и разблокировка — статус в карточке и списке, ссылка приглашения закрыта и снова открыта @desktop @data #6a993d795019333734edc22d', async ({ page, asUser }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await openCard(page);
    await changeStatus(page, 'חסום');
    await expect(statusRegion(page).getByRole('combobox', { name: 'סטטוס חדש' }).locator('option:checked')).toHaveText('חסום');

    await page.goto('/admin/businesses');
    const listRow = page.getByRole('table', { name: /^רשימת בתי העסק/ }).getByRole('row').filter({ hasText: BUSINESS_NAME });
    await expect(listRow.getByRole('cell').nth(4)).toHaveText('חסום');

    // AC3 / треб.4 «השפעה מיידית»: ссылка бизнеса перестаёт работать сразу.
    const guest = await asUser('guest');
    await guest.goto(`/invite/${firstToken}`);
    await expect(guest.getByRole('heading', { level: 1, name: 'החשבון העסקי אינו פעיל' })).toBeVisible();
    await expect(guest.getByRole('textbox')).toHaveCount(0);
    await expect(guest.getByText(BUSINESS_NAME)).toHaveCount(0);

    await openCard(page);
    await changeStatus(page, 'פעיל');
    await expect(statusRegion(page).getByRole('combobox', { name: 'סטטוס חדש' }).locator('option:checked')).toHaveText('פעיל');
    await expectJoinForm(guest, firstToken);
  });

  test('удаление — бизнеса нет в списке и в ответе admin_list_businesses, ссылка закрыта @desktop @data #6a993d795019333734edc22d', async ({ page, asUser }) => {
    expect(businessId, 'нужен бизнес из первого теста (serial)').toBeTruthy();
    await openCard(page);
    await statusRegion(page).getByRole('combobox', { name: 'סטטוס חדש' }).selectOption({ label: 'נמחק' });
    await statusRegion(page).getByRole('button', { name: 'עדכון סטטוס' }).click();
    await expect(page.getByText('בית העסק יוסר מהרשימה, משתמשיו לא יוכלו להתחבר ונתוניו לא יהיו נגישים לאף משתמש עסקי.')).toBeVisible();
    await page.getByRole('button', { name: 'אישור', exact: true }).click();
    await page.waitForURL('**/admin/businesses');
    await expect(page.getByText('בית העסק נמחק')).toBeVisible();
    deleted = true;

    // AC6: новая загрузка списка. Имя есть в сообщении об удалении — проверяем таблицу и ответ сервера.
    const listed = page.waitForResponse((r) => r.url().includes('/rpc/admin_list_businesses') && r.request().method() === 'POST');
    await page.goto('/admin/businesses');
    const listRes = await listed;
    expect(listRes.ok()).toBeTruthy();
    expect(await listRes.text(), 'удалённый бизнес в ответе admin_list_businesses').not.toContain(businessId);
    const table = page.getByRole('table', { name: /^רשימת בתי העסק/ });
    await expect(table).toBeVisible();
    await expect(table.getByText(BUSINESS_NAME)).toHaveCount(0);

    const guest = await asUser('guest');
    await guest.goto(`/invite/${firstToken}`);
    await expect(guest.getByRole('heading', { level: 1, name: 'החשבון העסקי אינו פעיל' })).toBeVisible();
    await expect(guest.getByRole('textbox')).toHaveCount(0);
  });
});
